import{_ as t,o as s,c as a,a3 as r}from"./chunks/framework.iKZ1V-y0.js";const m=JSON.parse('{"title":"2.1 Hello World: Ferrium Ore at a Fork in the Road","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"2\\\\.1 Hello World：蓝铁矿的命途分叉","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=EtRfKcfCGHwRQxAFs7gkqI","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-EtRfKcfCGHwRQxAFs7gkqI.md","filePath":"logistics/src/page-EtRfKcfCGHwRQxAFs7gkqI.md","lastUpdated":null}'),o={name:"logistics/src/page-EtRfKcfCGHwRQxAFs7gkqI.md"};function l(i,e,n,c,p,d){return s(),a("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="_2-1-hello-world-蓝铁矿的命途分叉" aria-hidden="true"></span><h1 id="_2-1-hello-world-ferrium-ore-at-a-fork-in-the-road" tabindex="-1">2.1 Hello World: Ferrium Ore at a Fork in the Road <a class="header-anchor" href="#_2-1-hello-world-ferrium-ore-at-a-fork-in-the-road" aria-label="Permalink to &quot;2\\.1 Hello World: Ferrium Ore at a Fork in the Road&quot;">​</a></h1><blockquote><p>Source page ID: <code>EtRfKcfCGHwRQxAFs7gkqI</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=EtRfKcfCGHwRQxAFs7gkqI" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Consider this automatic plan: <strong>make <strong><span class="mark-blue"><strong>Ferrium Parts</strong></span></strong> until a stash fills, then begin <strong><span class="mark-blue"><strong>Ferrium Bottles</strong></span></strong>.</strong> An <u>output-priority device</u> easily achieves this, below. After <span class="mark-blue">Ferrium Parts</span> fill the stash, the Fitting Unit gradually blocks,</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d4dc7795b1ef1870.q90-f9d858c02b714c06.webp" alt="21 Hello World: Ferrium Ore at a Fork in the Road"></p><p>Small but complete. This simple example contains most blocking-based production concepts:</p><ol><li><p><strong>Two production states (two routes)</strong>: <span class="mark-blue">Ferrium Parts</span> (30/m) and <span class="mark-blue">Ferrium Bottles</span> (15/m).</p></li><li><p><strong>Blocking signal</strong>: <span class="mark-blue">Ferrium Parts</span> first fill the stash; blocking then propagates upstream, gradually blocking the Fitting Unit.</p></li><li><p><strong>How states change</strong>: once the Fitting Unit and immediate upstream belt block, <span class="mark-blue">Ferrium</span> naturally flows to the Moulding Unit, starting <span class="mark-blue">Ferrium Bottle</span> production.</p></li></ol><p>These form the most basic blocking-production unit. Later structures may have more complex processes/layouts, but share this core logic.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-efb1e399d855a670.q90-23363ebc0ea99fec.webp" alt="21 Hello World: Ferrium Ore at a Fork in the Road"></p><p><a href="./page-ZDxRoi4GKekmLzgHNaf4fQ">2.2 Two Branches Bloom: Switching-Type and Balancing-Type Blocking</a></p></div>',1)])])}const u=t(o,[["render",l]]);export{m as __pageData,u as default};
